import React, { useState, useEffect, useRef } from 'react';
import { createRoot } from 'react-dom/client';
import { BookOpen, Network, ScanLine, ChartNoAxesCombined, Lightbulb, Compass, ArrowUpRight, ArrowRight, ChevronRight, ChevronDown, Check, X, Plus, FileText, History, GraduationCap, CircleHelp, Settings2, ShieldCheck, Leaf, PanelLeftClose, Menu, Download, Upload, Quote, CornerDownRight, ArrowDown, Circle, CheckCircle2, Clock3, Flag, RotateCcw, ExternalLink, Search, LockKeyhole, Feather, SlidersHorizontal, LoaderCircle, Cpu, ClipboardList } from 'lucide-react';
import { CRITERIA, SAMPLE, SEEDS, CLOSURE_CHECKS } from './data.mjs';
import { newSession, activeChallenges, escalate, saveResponse, resolve, dismiss, saveAuthorship, rateAuthorship, upgradeSession, exportSession, parseDraft, clone, words, event, validateModelChallenges } from './engine.mjs';
import './styles.css';

const iconMap={BookOpen,Network,ScanLine,ChartNoAxesCombined,Lightbulb,Compass};
const KEY='better-not-more-session-v1';
const loadSession=()=>{try{const s=JSON.parse(localStorage.getItem(KEY));if(s?.schemaVersion===1&&s.manuscript?.sections?.length&&Array.isArray(s.challenges)&&Array.isArray(s.events))return upgradeSession(s);}catch{}return newSession();};
const download=(name,data,type='application/json')=>{const u=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
function Icon({name,...props}){const C=iconMap[name]||BookOpen;return <C {...props}/>;}
function App(){
  const [session,setSession]=useState(loadSession),[page,setPage]=useState('workspace'),[tab,setTab]=useState('manuscript'),[modal,setModal]=useState(null),[toast,setToast]=useState(''),[mobileNav,setMobileNav]=useState(false),[saveError,setSaveError]=useState(false);
  const [passage,setPassage]=useState(null),[focusRef,setFocusRef]=useState(null),[modelStatus,setModelStatus]=useState(null),[busy,setBusy]=useState(false);
  const active=activeChallenges(session),completed=session.challenges.filter(c=>c.status==='resolved').length;
  const selected=session.challenges.find(c=>c.id===session.selected)||active[0]||session.challenges[0];
  const criterion=CRITERIA.find(c=>c.id===selected?.criterion)||CRITERIA[0];
  useEffect(()=>{try{localStorage.setItem(KEY,JSON.stringify(session));setSaveError(false);}catch{setSaveError(true);}},[session]);
  useEffect(()=>{if(toast){const id=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(id);}},[toast]);
  const notify=(t)=>setToast(t);
  const update=fn=>{try{setSession(fn(session));}catch(e){notify(e.message);}};
  const navigate=p=>{setPage(p);setMobileNav(false);};
  function select(c){setSession(s=>({...s,selected:c.id}));setPassage(c.sectionId);setTab('manuscript');setPage('workspace');}
  useEffect(()=>{if(passage&&page==='workspace'&&tab==='manuscript'){document.getElementById(`section-${passage}`)?.scrollIntoView({behavior:'smooth',block:'start'});}},[passage,page,tab,selected?.id]);
  function focusManuscript(){setTab('manuscript');setPassage(null);requestAnimationFrame(()=>setPassage(selected.sectionId));}
  function locate(){if(selected.referenceId){setTab('references');setFocusRef(selected.referenceId);}else {setTab('manuscript');setPassage(null);requestAnimationFrame(()=>setPassage(selected.sectionId));}}
  function exportLog(){download(`better-not-more-session-${session.id.slice(0,8)}.json`,JSON.stringify(exportSession(session),null,2));notify('Session, evidence, revisions, and author explanations exported.');}
  function exportDraft(){download('manuscript-revised.md',`# ${session.manuscript.title}\n\n${session.manuscript.sections.map(s=>`## ${s.label}\n\n${s.paragraphs.join('\n\n')}`).join('\n\n')}`,'text/markdown');notify('Your current manuscript has been exported.');}
  async function checkModel(){setBusy(true);try{const r=await fetch('/api/status');if(!r.ok||!r.headers.get('content-type')?.includes('application/json'))throw new Error('Local gateway not running. Follow the local setup instructions below.');const data=await r.json();setModelStatus(data);if(!data.ready)throw new Error(data.message||'The local model is not available.');notify(`Connected to ${data.model}.`);}catch(e){setModelStatus({ready:false,message:e.message});}finally{setBusy(false);}}
  async function runModel(){setBusy(true);try{const r=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({manuscript:session.manuscript})});const data=await r.json();if(!r.ok)throw new Error(data.error||'The local model could not complete the analysis.');const challenges=validateModelChallenges({challenges:data.challenges},session.manuscript);setSession(s=>({...s,challenges,selected:challenges[0].id,mode:'local',events:[...s.events,event('local_model_analysis','Local model produced passage-verified challenges.',{model:data.model})]}));setModal(null);notify('Local model challenges are ready. Each quoted passage was checked.');}catch(e){notify(e.message);}finally{setBusy(false);}}
  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav?'mobile-open':''}`}>
      <a className="brand" href="#" onClick={e=>{e.preventDefault();navigate('workspace');}}><span className="brand-symbol">b<span>↗</span></span><span>better, not more<span className="brand-sub">RESEARCH JUDGMENT STUDIO</span></span></a>
      <div className="sidebar-label">YOUR WORKSPACE</div>
      <nav aria-label="Main navigation">
        {[['workspace',BookOpen,'Learning workspace'],['log',History,'Research log'],['authorship',ClipboardList,'Explain your changes']].map(([id,C,label])=><button key={id} className={`nav-item ${page===id?'selected':''}`} onClick={()=>navigate(id)}><C size={18}/><span>{label}</span>{id==='log'&&<span className="nav-count">{session.events.length}</span>}</button>)}
      </nav>
      <div className="sidebar-divider"/>
      <div className="sidebar-label team-label">YOUR LEARNING TEAM <span>6</span></div>
      <div className="agent-list">{CRITERIA.map(c=>{const ch=session.challenges.find(x=>x.criterion===c.id);const isActive=active.some(x=>x.id===ch?.id),done=ch?.status==='resolved';return <button key={c.id} className={`agent-nav ${selected?.criterion===c.id&&page==='workspace'?'current':''}`} onClick={()=>ch?select(ch):setModal({type:'criterion',criterion:c})}><span className="agent-icon" style={{color:c.color}}><Icon name={c.icon} size={17}/></span><span>{c.short}<small>{done?'Reflection complete':ch?.status==='disputed'?'Under review':isActive?'Ready to explore':'Waiting its turn'}</small></span>{done?<Check size={14}/>:isActive?<span className="status-dot"/>:null}</button>;})}</div>
      <div className="sidebar-bottom"><div className="sidebar-note"><span className="plant-icon"><Leaf size={21}/></span><p>Better research starts<br/>with your judgment.</p><span className="tiny">We ask. You think. You write.</span></div><button className={`nav-item ${page==='about'?'selected':''}`} onClick={()=>navigate('about')}><CircleHelp size={18}/>How it works<ArrowUpRight size={15}/></button><div className="profile"><span className="avatar">R</span><div>Researcher workspace<small>Draft saved in this browser</small></div><button className="icon-button light" aria-label="Workspace settings" onClick={()=>setModal({type:'settings'})}><Settings2 size={17}/></button></div></div>
    </aside>
    {mobileNav&&<button className="nav-scrim" onClick={()=>setMobileNav(false)} aria-label="Close navigation"/>}
    <div className="main-shell">
      <header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-toggle" aria-label="Open navigation" onClick={()=>setMobileNav(true)}><Menu size={20}/></button><span>Research studio</span><ChevronRight size={14}/><strong>{{workspace:'Learning workspace',log:'Research log',authorship:'Explain your changes',about:'How it works'}[page]}</strong></div><div className="topbar-right"><span className="private-label"><ShieldCheck size={15}/>{saveError?'Storage full · export your work':'Saved on this device'}</span><button className="button small outline" onClick={exportLog}><Download size={15}/><span>Export session</span></button></div></header>
      <main>
      {page==='workspace'&&<>
        <div className="page-heading"><div><div className="eyebrow"><span className="small-line"/> A SPACE FOR DEEPER THINKING</div><h1>Your research. Your reasoning.</h1><p>Six perspectives to challenge your thinking, one question at a time.</p></div><button className="button outline new-manuscript" onClick={()=>setModal({type:'upload'})}><Plus size={17}/>New manuscript</button></div>
        <div className="session-strip"><div className="session-mode"><span className="live-dot"/><strong>{session.mode==='sample'?'Explore a sample session':session.mode==='local'?'Local model session':'Guided reading session'}</strong><span>{session.mode==='sample'?'Fictional draft · prepared questions':session.mode==='local'?'Model questions · exact quotes verified':'Your draft · general reading prompts'}</span></div><button onClick={()=>setModal({type:'settings'})} className="strip-settings"><SlidersHorizontal size={15}/>Session settings<ChevronRight size={15}/></button></div>
        <div className="session-overview"><div className="session-progress"><span className="progress-circle" style={{'--progress':`${completed/session.challenges.length*100}%`}}><span>{completed}<small>/ {session.challenges.length}</small></span></span><div><strong>Make room for reflection.</strong><p>{active.length} open {active.length===1?'challenge':'challenges'} at a time. You set the pace.</p></div></div><div className="overview-metric"><span className="metric-icons"><FileText size={17}/></span><div><strong>{session.manuscript.sections.length} sections</strong><small>In your manuscript</small></div></div><div className="overview-metric"><span className="metric-icons"><CheckCircle2 size={18}/></span><div><strong>A clear point of closure</strong><small>Check the criterion, then move on</small></div></div><button className="icon-button" title="About closing an issue" onClick={()=>setModal({type:'closure'})}><CircleHelp size={18}/></button></div>
        <button className="jump-to-tutor" onClick={()=>document.querySelector('.tutor-panel')?.scrollIntoView({behavior:'smooth',block:'start'})}>Start with your tutor’s question<ArrowDown size={14}/></button><div className="workspace-grid"><section className="manuscript-panel panel"><div className="panel-tabs"><div role="tablist" aria-label="Manuscript and references"><button role="tab" aria-selected={tab==='manuscript'} className={tab==='manuscript'?'active':''} onClick={()=>setTab('manuscript')}><FileText size={16}/>Manuscript</button><button role="tab" aria-selected={tab==='references'} className={tab==='references'?'active':''} onClick={()=>setTab('references')}><BookOpen size={16}/>References<span className="count-badge">{session.manuscript.references.length}</span></button></div><button className="icon-button" aria-label="Download current manuscript" onClick={exportDraft}><Download size={16}/></button></div>
          {tab==='manuscript'?<div className="document-scroll"><div className="document-meta"><span>{session.manuscript.type}</span><span>{words(session.manuscript.sections.flatMap(s=>s.paragraphs).join(' ')).toLocaleString()} words</span></div><h2 className="document-title">{session.manuscript.title}</h2><p className="document-subtitle">{session.manuscript.subtitle}</p><div className="document-rule"/>{session.manuscript.sections.map((s,i)=><article key={s.id} id={`section-${s.id}`} className="document-section"><h3><span>{String(i+1).padStart(2,'0')}</span>{s.label}{selected?.sectionId===s.id&&<span className="reading-marker">CURRENT FOCUS</span>}</h3>{s.paragraphs.map((p,j)=>{const highlight=selected?.sectionId===s.id&&selected.paragraph===j;const quote=selected?.status==='resolved'?selected.revision:selected?.quote;let parts=highlight&&quote&&p.includes(quote)?p.split(quote):null;return <p key={j} className={highlight?'focused-paragraph':''}>{parts?<>{parts[0]}<mark className={selected.status==='resolved'?'revised':''}>{quote}</mark>{parts.slice(1).join(quote)}</>:p}{highlight&&selected.status==='open'&&<span className="margin-marker" title="A question about this passage"><Quote size={14}/></span>}</p>;})}</article>)}<div className="document-end"><Feather size={16}/><span>{session.manuscript.mode==='sample'?'This manuscript and its cited sources are fictional teaching material.':'Your words stay yours.'}</span></div></div>:<div className="references-scroll"><div className="reference-heading"><div className="eyebrow">YOUR EVIDENCE LIBRARY</div><h2>Read the source.</h2><p>Inspect the argument behind the citation.</p></div>{session.manuscript.references.map(r=><article key={r.id} className={`reference-card ${focusRef===r.id?'reference-focused':''}`}><div className="reference-top"><span className="reference-icon"><BookOpen size={18}/></span><span>{r.synthetic?'SYNTHETIC TEACHING SOURCE':'UPLOADED REFERENCE'}</span></div><h3>{r.title}</h3><p className="reference-name">{r.name}</p><blockquote>{r.text}</blockquote><div className="source-location"><FileText size={13}/>{r.location}</div></article>)}{!session.manuscript.references.length&&<div className="empty-state"><BookOpen size={32}/><h3>Add the sources you cite.</h3><p>Without source text, the tutor cannot verify a citation. Add a reference to make comparison possible.</p></div>}<button className="button outline full" onClick={()=>setModal({type:'reference'})}><Plus size={16}/>Add a reference</button></div>}
        </section><section className="tutor-column"><Tutor key={selected?.id} session={session} challenge={selected} criterion={criterion} active={active} onSelect={select} onUpdate={update} notify={notify} onLocate={locate} onEvidence={focusManuscript} onDispute={()=>setModal({type:'dispute',id:selected.id})} onCriterion={()=>setModal({type:'criterion',criterion})}/><div className="human-note"><Feather size={16}/><span>The questions are ours. The judgment is yours.</span></div></section></div>
        <div className="workspace-footer"><span>Six editorial criteria. Every change remains yours.</span><button onClick={()=>navigate('about')}>Explore the approach<ArrowUpRight size={13}/></button></div>
      </>}
      {page==='log'&&<ResearchLog session={session} onExport={exportLog} onDraft={exportDraft} onAuthorship={()=>navigate('authorship')}/>}
      {page==='authorship'&&<Authorship session={session} setSession={setSession} notify={notify} onStart={()=>navigate('workspace')}/>}
      {page==='about'&&<About onStart={()=>navigate('workspace')} onModel={()=>setModal({type:'settings'})}/>}
      </main>
    </div>
    {modal&&<Modal title={{upload:'Bring your research to the table',reference:'Add a cited source',settings:'Your session, your pace',criterion:modal.criterion?.name,dispute:'Challenge the challenge',closure:'When is an issue ready to close?',reset:'Start a fresh sample session?'}[modal.type]} onClose={()=>{if(!busy)setModal(null);}}>
      {modal.type==='upload'&&<UploadForm onDone={m=>{setSession(newSession(m));setPage('workspace');setTab('manuscript');setPassage(null);setModal(null);notify('Your draft is ready. Guided prompts help you inspect each criterion.');}}/>}
      {modal.type==='reference'&&<ReferenceForm onDone={r=>{setSession(s=>({...s,manuscript:{...s.manuscript,references:[...s.manuscript.references,r]},events:[...s.events,event('reference_added','Researcher added a source.',{title:r.title})]}));setModal(null);notify('Reference added to your evidence library.');}}/>}
      {modal.type==='criterion'&&<><div className="criterion-modal-icon"><Icon name={modal.criterion.icon} size={29}/></div><p className="modal-intro">{modal.criterion.standard}</p><div className="plain-label">A QUESTION TO KEEP IN MIND</div><p className="serif-question">{modal.criterion.question}</p><div className="hint-box"><div className="plain-label">PRACTICAL CHECK BEFORE CLOSING</div><p>{CLOSURE_CHECKS[modal.criterion.id]}</p></div><p className="subtle">The learning team applies this criterion through questions and evidence. See How it works for the literature reference.</p></>}
      {modal.type==='settings'&&<><p className="modal-intro">Keep the work focused enough to think carefully.</p><label className="field-label" htmlFor="challenge-cap">Maximum open challenges</label><select id="challenge-cap" value={session.cap} onChange={e=>{const cap=Number(e.target.value);setSession(s=>({...s,cap,selected:activeChallenges({...s,cap})[0]?.id||s.selected,events:[...s.events,event('challenge_cap_changed',`Open challenge cap set to ${cap}.`)]}));}}>{[1,2,3].map(n=><option key={n} value={n}>{n} at a time</option>)}</select><p className="field-help">At most this many questions are open at once. Closing or disputing one brings forward the next waiting question.</p><details className="settings-section"><summary><Cpu size={18}/>Optional technical setup: a local model</summary><p>The sample uses curated questions. For model-generated questions, run this app locally with an Ollama model. The hosted demo does not send drafts to a model.</p><code className="setup-code">npm run build<br/>OLLAMA_MODEL=your-local-model npm run local</code><p className="field-help">Open http://127.0.0.1:4173, then connect here. Only a loopback model endpoint is accepted.</p>{modelStatus&&<p className={modelStatus.ready?'success-text':'error-text'}>{modelStatus.ready?`Available: ${modelStatus.model}`:modelStatus.message}</p>}<div className="button-row"><button className="button outline small" disabled={busy} onClick={checkModel}>{busy?<LoaderCircle className="spin" size={15}/>:<Cpu size={15}/>}Check connection</button>{modelStatus?.ready&&<button className="button primary small" disabled={busy||session.events.some(e=>e.type==='reasoning_recorded')} onClick={runModel}>{busy?'Reading…':'Generate grounded questions'}</button>}</div><p className="field-help">Model analysis is available before your first response, preserving the session’s evidence trail. Uploaded text is data, not an instruction to the tutor.</p></details><div className="settings-section"><h3>Fresh start</h3><p>Export your current session before replacing it.</p><button className="button outline small" onClick={()=>setModal({type:'reset'})}><RotateCcw size={14}/>Load sample manuscript</button></div></>}
      {modal.type==='reset'&&<><p className="modal-intro">This replaces the current draft, responses, and author explanations in this browser. Download a copy first if you want to keep them.</p><div className="button-row"><button className="button outline" onClick={exportLog}><Download size={16}/>Export current session</button><button className="button primary" onClick={()=>{setSession(newSession());setModal(null);setPage('workspace');setTab('manuscript');notify('A fresh sample session is ready.');}}>Start fresh</button></div></>}
      {modal.type==='dispute'&&<ReasonForm label="Why might this challenge be mistaken?" placeholder="Identify what the tutor has misunderstood, with evidence…" button="Record disagreement" onSubmit={reason=>{try{setSession(dismiss(session,modal.id,reason));setModal(null);notify('Disagreement recorded for human review.');}catch(e){throw e;}}}/>}
      {modal.type==='closure'&&<><p className="modal-intro">The proposed agent team closes an issue when a revision meets its criterion well enough to move on. This demo makes that decision visible.</p><ol className="steps-list"><li>Record your reasoning about the cited passage.</li><li>Write your revision, or explain why the passage should stand.</li><li>Review the criterion check and confirm that your decision addresses it.</li><li>Close the issue. The next waiting question becomes available.</li></ol><p className="subtle">In this demo, you confirm the check. Automated assessment of a revision is not implemented, and closure is not a verified quality score. If the challenge is mistaken, record a disagreement instead.</p></>}
    </Modal>}
    {toast&&<div className="toast" role="status"><CircleHelp size={18}/>{toast}<button className="icon-button" aria-label="Dismiss message" onClick={()=>setToast('')}><X size={15}/></button></div>}
  </div>;
}

function Tutor({session,challenge:c,criterion,active,onSelect,onUpdate,notify,onLocate,onEvidence,onDispute,onCriterion}){
  const [response,setResponse]=useState(c?.draftResponse||c?.response||''),[confidence,setConfidence]=useState(c?.draftConfidence??c?.confidence??50),[revision,setRevision]=useState(c?.draftRevision||''),[decision,setDecision]=useState('revise'),[closureConfirmed,setClosureConfirmed]=useState(false);
  const saveDraft=(key,value)=>onUpdate(s=>({...s,challenges:s.challenges.map(x=>x.id===c.id?{...x,[key]:value}:x)}));
  if(!c)return <div className="panel empty-state">No challenges available.</div>;
  const available=active.some(x=>x.id===c.id);
  const isClosed=c.status!=='open';
  function submit(e){e.preventDefault();if(/\b(write|rewrite|draft|generate|polish)\b.{0,50}\b(for me|paragraph|manuscript|answer|section|text)\b/i.test(response)){notify('This tutor only asks questions. What is your own interpretation of the cited passage?');return;}onUpdate(s=>saveResponse(s,c.id,response,confidence));}
  return <div className="tutor-panel panel"><div className="tutor-header"><div className="tutor-avatar" style={{background:`${criterion.color}18`,color:criterion.color}}><Icon name={criterion.icon} size={24}/></div><div><div className="eyebrow">YOUR {criterion.short.toUpperCase()} TUTOR</div><strong>A closer look at {criterion.short.toLowerCase()}</strong></div><button className="icon-button" aria-label="About this criterion" onClick={onCriterion}><CircleHelp size={17}/></button></div>
    <div className="challenge-tabs"><span>{isClosed?'SESSION PROGRESS':available?'OPEN CHALLENGES':'QUEUED CHALLENGE'}</span><div>{active.map((a,i)=><button key={a.id} title={CRITERIA.find(cr=>cr.id===a.criterion)?.name} aria-label={`Open challenge ${i+1}`} className={a.id===c.id?'selected':''} onClick={()=>onSelect(a)}>{i+1}</button>)}{active.length===0&&<Check size={17}/>}</div><span className="challenge-cap">{active.length} / {session.cap}</span></div>
    {!available&&!isClosed?<div className="paused-challenge"><Clock3 size={30}/><h2>One thing at a time.</h2><p>This criterion is waiting its turn. Close or dispute an open question to make room for the next perspective.</p>{active[0]&&<button className="button primary" onClick={()=>onSelect(active[0])}>Back to an open challenge<ArrowRight size={16}/></button>}</div>:isClosed?<div className="resolved-card"><span className="resolved-symbol">{c.status==='resolved'?<Check size={28}/>:<Flag size={26}/>}</span><div className="eyebrow">{c.status==='resolved'?'REFLECTION RECORDED':'DISAGREEMENT RECORDED'}</div><h2>{c.status==='resolved'?'The decision is yours.':'Your judgment matters.'}</h2><p>{c.status==='resolved'?'Your reasoning and decision are in the research log. Completion records your action; it is not a quality score.':'The passage and your objection are preserved for human review. A challenge is a question, not a verdict.'}</p><blockquote>{c.response||c.disputeReason}</blockquote>{active[0]&&<button className="button primary full" onClick={()=>onSelect(active[0])}>Next perspective<ArrowRight size={16}/></button>}</div>:<>
    <div className="tutor-body"><div className="challenge-eyebrow"><span>REFLECTION {criterion.number}</span><span><span className="mini-dot"/>Evidence attached</span></div><h2>{c.title}</h2><p className="learning-question">{c.question}</p><button className="evidence-card" onClick={onEvidence}><div><Quote size={15}/><span>FROM YOUR MANUSCRIPT</span><ArrowUpRight size={14}/></div><blockquote>“{c.quote}”</blockquote><span className="evidence-location"><FileText size={12}/>{session.manuscript.sections.find(s=>s.id===c.sectionId)?.label} · ¶ {c.paragraph+1}</span></button>
    <div className="support-ladder"><span className="ladder-line"/>{['Question','Hint','What is missing'].map((n,i)=><div key={n} className={c.level>=i?'reached':''}><span>{c.level>i?<Check size={10}/>:i+1}</span><small>{n}</small></div>)}</div>
    {c.level>=1&&<div className="hint-box"><div className="plain-label"><Lightbulb size={14}/>A SMALL NUDGE</div><p>{c.hint}</p></div>}
    {c.level>=2&&<div className="hint-box location-hint"><div className="plain-label"><BookOpen size={14}/>{session.mode==='guided'?'WHAT TO CHECK':'WHAT IS MISSING'}</div><p>{c.missing}</p>{c.sourceQuote&&<blockquote>“{c.sourceQuote}”</blockquote>}<button className="text-link" onClick={onLocate}>Open the passage<ArrowUpRight size={13}/></button></div>}
    <div className="support-actions">{c.level<2?<button className="text-link" onClick={()=>onUpdate(s=>escalate(s,c.id))}>{c.level===0?<Lightbulb size={15}/>:<BookOpen size={15}/>} {c.level===0?'A hint, please':'Make the gap explicit'}<ChevronRight size={13}/></button>:<span className="support-stop"><Feather size={13}/>The next step is your reasoning.</span>}<button className="quiet-button" onClick={onDispute} title="Flag a mistaken challenge"><Flag size={13}/>Disagree?</button></div>
    </div>
    {!c.response?<form className="response-form" onSubmit={submit}><label htmlFor={`response-${c.id}`}>What do you notice?</label><p className="field-help">Explain it in your own words. Uncertainty is welcome.</p><textarea id={`response-${c.id}`} value={response} onChange={e=>{setResponse(e.target.value);saveDraft('draftResponse',e.target.value);}} placeholder="I notice that… The evidence suggests…" rows={4} maxLength={6000}/><div className="confidence-row"><label htmlFor={`confidence-${c.id}`}>How confident are you?</label><span>{confidence}%</span></div><input id={`confidence-${c.id}`} aria-label="Confidence in your reasoning" type="range" min="0" max="100" step="5" value={confidence} onChange={e=>{setConfidence(Number(e.target.value));saveDraft('draftConfidence',Number(e.target.value));}}/><div className="response-bottom"><span>{words(response)} words</span><button type="submit" className="button primary" disabled={words(response)<8}>Share your reasoning<ArrowRight size={16}/></button></div></form>:<div className="response-form revision-form"><div className="recorded-label"><CheckCircle2 size={16}/>Your reasoning is recorded</div><blockquote className="own-response">{c.response}</blockquote><label htmlFor={`revision-${c.id}`}>What will you change, and why?</label><p className="field-help">Write your own revision or retain the passage based on your recorded justification. Then check the criterion below.</p><div className="decision-toggle"><button className={decision==='revise'?'selected':''} onClick={()=>{setDecision('revise');setClosureConfirmed(false);}}><Feather size={14}/>Revise the passage</button><button className={decision==='retain'?'selected':''} onClick={()=>{setDecision('retain');setClosureConfirmed(false);}}>Retain with reasons</button></div>{decision==='revise'&&<textarea id={`revision-${c.id}`} value={revision} onChange={e=>{setRevision(e.target.value);setClosureConfirmed(false);saveDraft('draftRevision',e.target.value);}} placeholder="Write your own replacement for the quoted passage…" rows={4} maxLength={10000}/>}<div className="closure-check"><div className="plain-label">CHECK BEFORE CLOSING</div><p>{CLOSURE_CHECKS[c.criterion]}</p><label className="checkbox-label"><input type="checkbox" checked={closureConfirmed} onChange={e=>setClosureConfirmed(e.target.checked)}/><span>I have checked this criterion and can justify my decision.</span></label><p className="field-help">Your confirmation is recorded. The demo does not automatically judge the revision.</p></div><button className="button primary full" disabled={!closureConfirmed||(decision==='revise'&&(!revision.trim()||revision.trim()===c.quote))} onClick={()=>onUpdate(s=>resolve(s,c.id,revision,decision,closureConfirmed))}>Close this issue<Check size={16}/></button></div>}
    </>}
  </div>;
}

function ResearchLog({session,onExport,onDraft,onAuthorship}){const [filter,setFilter]=useState('all');const closed=session.challenges.filter(c=>c.status==='resolved');const items=[...session.events].reverse().filter(e=>filter==='all'||e.criterion===filter);return <><div className="page-heading"><div><div className="eyebrow"><span className="small-line"/>A VISIBLE TRAIL OF THINKING</div><h1>Your reasoning, on the record.</h1><p>Every question, source, judgment, and revision stays connected.</p></div><button className="button outline" onClick={onExport}><Download size={16}/>Export research log</button></div><div className="stat-grid"><Stat value={session.events.filter(e=>e.type==='reasoning_recorded').length} label="Reasoning steps"/><Stat value={closed.length} label="Decisions recorded"/><Stat value={session.challenges.filter(c=>c.status==='disputed').length} label="Challenges disputed"/><Stat value={Object.keys(session.authorship.submitted).length} label="Changes explained"/></div>{closed.some(c=>c.decision==='revise')&&<section className="panel discovery-panel"><div><div className="eyebrow"><Feather size={14}/>CAN YOU ACCOUNT FOR THE CHANGE?</div><h2>Return to your revised passages.</h2><p>Explain what changed, why you changed it, and which evidence supports your decision.</p></div><button className="button outline" onClick={onAuthorship}>Explain your changes<ArrowRight size={16}/></button></section>}<div className="log-toolbar"><h2>Session history <span className="count-badge">{items.length}</span></h2><select aria-label="Filter history by criterion" value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">All criteria</option>{CRITERIA.map(c=><option key={c.id} value={c.id}>{c.short}</option>)}</select></div><div className="panel timeline">{items.map(e=><article key={e.id} className="timeline-entry"><div className={`timeline-symbol ${e.type==='challenge_resolved'?'done':''}`}>{e.type==='support_faded'?<Leaf size={17}/>:e.type==='challenge_resolved'?<Check size={17}/>:e.type==='challenge_disputed'?<Flag size={17}/>:<CornerDownRight size={17}/>}</div><div className="timeline-content"><div className="timeline-heading"><h3>{e.detail}</h3><time>{new Date(e.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></div><div className="log-tags">{e.criterion&&<span>{CRITERIA.find(c=>c.id===e.criterion)?.name}</span>}{e.level!==undefined&&<span>{['Question only','Hint used','Gap made explicit'][e.level]}</span>}{e.confidence!==undefined&&<span>{e.confidence}% confidence · self-reported</span>}{e.rating!==undefined&&<span>Human rating: {e.rating===''?'withdrawn':`${e.rating} / 2`} · not blinded</span>}</div>{e.question&&<p className="log-question">{e.question}</p>}{e.missing&&<p className="log-question">{e.missing}</p>}{e.quote&&<blockquote>{e.quote}</blockquote>}{e.response&&<div className="log-response"><span className="plain-label">RESEARCHER’S REASONING</span><p>{e.response}</p></div>}{e.revision&&(e.decision==='revise'||e.type==='authorship_explained')&&<div className="log-revision"><span className="plain-label">RESEARCHER’S REVISION</span><p>{e.revision}</p></div>}{e.reason&&<p>{e.reason}</p>}{e.verification&&<p className="subtle">{e.verification}</p>}</div></article>)}{!items.length&&<div className="empty-state"><History size={30}/><p>No events for this criterion yet.</p></div>}</div><div className="log-footer"><p>Session records show what happened. A human rater assesses the quality of the reasoning.</p><button className="text-link" onClick={onDraft}>Download your revised manuscript<ArrowUpRight size={14}/></button></div></>;}
function Stat({value,label}){return <div className="stat"><span>{String(value).padStart(2,'0')}</span><p>{label}</p></div>;}

function Authorship({session,setSession,notify,onStart}) {
  const revisions=session.challenges.filter(c=>c.status==='resolved'&&c.decision==='revise');
  const [selected,setSelected]=useState(null);
  const c=revisions.find(c=>c.id===selected)||revisions[0],state=session.authorship;
  const response=c?state.answers[c.id]||'':'';
  const submitted=c&&state.submitted[c.id];
  const updateAnswer=value=>setSession(s=>({...s,authorship:{...s.authorship,answers:{...s.authorship.answers,[c.id]:value}}}));
  function submit(){try{setSession(saveAuthorship(session,c.id,response));notify('Your explanation is recorded. A human reviewer can now enter an assessment.');}catch(e){notify(e.message);}}
  return <><div className="page-heading"><div><div className="eyebrow"><span className="small-line"/>THE AUTHOR BEHIND THE REVISION</div><h1>Can you explain what changed?</h1><p>Return to your own revised passages and account for the decisions you made.</p></div></div>
    <div className="transfer-notice"><ClipboardList size={23}/><p><strong>A demonstration of the authorship measure.</strong> In the proposed study, researchers explain a sample of their changes and independent raters assess those explanations. Here, you can choose any revised passage. This is not a blinded study or a test of lasting skill.</p></div>
    {!c?<section className="panel empty-state"><Feather size={32}/><h2>Your revisions will appear here.</h2><p>Revise and close at least one passage in the learning workspace, then return to explain your change.</p><button className="button primary" onClick={onStart}>Go to the learning workspace<ArrowRight size={16}/></button></section>:<div className="transfer-layout"><nav className="panel transfer-nav" aria-label="Your revised passages"><div className="plain-label">YOUR CHANGED PASSAGES</div>{revisions.map((r,i)=><button key={r.id} className={r.id===c.id?'active':''} onClick={()=>setSelected(r.id)}><span>{String(i+1).padStart(2,'0')}</span><div>{CRITERIA.find(x=>x.id===r.criterion)?.short}<small>{state.submitted[r.id]?'Explanation submitted':'Your explanation needed'}</small></div>{state.submitted[r.id]?<CheckCircle2 size={16}/>:<ChevronRight size={16}/>}</button>)}</nav>
      <section className="panel transfer-card"><div className="eyebrow">{CRITERIA.find(x=>x.id===c.criterion)?.name}</div><h2>{c.title}</h2><div className="plain-label">BEFORE</div><blockquote>{c.quote}</blockquote><div className="plain-label">YOUR REVISION</div><blockquote>{c.revision}</blockquote><label className="field-label" htmlFor="authorship-response">What changed, why, and on what evidence?</label><p className="field-help">Explain the decision in your own words, including any limitations that remain. No suggested answer is supplied.</p><textarea id="authorship-response" rows={6} maxLength={6000} value={response} disabled={!!submitted} onChange={e=>updateAnswer(e.target.value)} placeholder="I changed… because… The evidence supports… A remaining limitation is…"/>
      {!submitted?<button className="button primary full" disabled={words(response)<12} onClick={submit}>Record my explanation<Check size={16}/></button>:<div className="rater-panel"><div className="plain-label">HUMAN REVIEW · DEMONSTRATION</div><p>Assess whether the author identifies the substantive change, connects it to evidence and the relevant criterion, and recognizes remaining limits. Fluent wording alone is not sufficient.</p><label className="field-label" htmlFor="authorship-rating">Human reviewer’s assessment</label><select id="authorship-rating" value={state.ratings[c.id]??''} onChange={e=>{try{setSession(rateAuthorship(session,c.id,e.target.value));}catch(error){notify(error.message);}}}><option value="">Awaiting human review</option><option value="0">0 · Change not adequately explained</option><option value="1">1 · Partially explained and justified</option><option value="2">2 · Explained with evidence and appropriate limits</option></select><p className="field-help">This illustrative rubric is not validated. Ratings entered here are visible and not independent or blinded. The proposed study needs a separate rater workflow.</p></div>}</section></div>}
  </>;
}

function About({onStart,onModel}){return <>
  <div className="page-heading"><div><div className="eyebrow"><span className="small-line"/>BETTER, NOT MORE</div><h1>Better drafts. Decisions you can defend.</h1><p>A learning workspace that questions research drafts against six editorial criteria.</p></div></div>
  <section className="about-hero"><span className="about-art" aria-hidden="true"><span/><span/><span/><Feather size={58}/></span><div><div className="eyebrow">THE QUESTION BEHIND THE PROJECT</div><h2>Can questions improve a draft<br/>while keeping the author in charge?</h2><p>Each learning agent focuses on one criterion. It draws attention to a passage, asks you to examine the reasoning, and identifies gaps when you need more support. You decide what to change and write every revision.</p><button className="button cream" onClick={onStart}>Explore the learning workspace<ArrowRight size={17}/></button></div></section>
  <div className="section-heading"><span className="eyebrow">SIX PERSPECTIVES, ONE HUMAN AUTHOR</span><h2>What the learning team looks for.</h2></div><div className="criteria-grid">{CRITERIA.map(c=><article className="panel criterion-card" key={c.id}><div><Icon name={c.icon} size={23}/><span>{c.number}</span></div><h3>{c.name}</h3><p>{c.standard}</p></article>)}</div>
  <div className="section-heading"><span className="eyebrow">FIVE RULES THAT SHAPE THE EXPERIENCE</span><h2>Preserve the work of thinking.</h2></div><div className="rules-list">{[
    ['01','The author writes every revision','The agents ask questions and identify gaps. They never supply sentences for the manuscript.'],
    ['02','Every challenge points to evidence','A challenge means a question about a specific passage. You can inspect the quoted text and any attached source, and record a disagreement if the question is mistaken.'],
    ['03','More support, without writing the remedy','Start with a question. If needed, ask for a hint, then an explicit statement of what is missing or inconsistent. The revision remains yours.'],
    ['04','A clear point of closure','The proposed team closes an issue once the revision meets the criterion for practical purposes. Here, you review a criterion check and confirm closure yourself; automated revision assessment remains to be implemented.'],
    ['05','A manageable number of open questions','The team sequences its questions instead of presenting every issue at once. This demo allows up to three open questions, adjustable to one or two in Session settings.']
  ].map(([n,title,body])=><div key={n}><span>{n}</span><h3>{title}</h3><p>{body}</p></div>)}</div>
  <section className="panel queue-explainer"><div className="eyebrow">THREE OPEN QUESTIONS AT A TIME</div><h2>What happens to the other questions?</h2><p>In the sample, Literature, Theory–method, and Methods are available first. Analysis, Inferences, and Practice wait their turn. You choose which open question to work on. When you close an issue or record a disagreement, the next waiting question becomes available.</p><p>This is all that “three-challenge orchestration” means here: coordinating the order and number of open questions so the researcher can focus. It describes the workload limit and sequence; each question remains linked to one criterion.</p><div className="queue-example" aria-label="Example: three open questions, then analysis becomes available"><span>Literature</span><span>Theory–method</span><span>Methods</span><ArrowRight size={18}/><span className="waiting">Analysis waits for a space</span></div></section>
  <div className="section-heading"><span className="eyebrow">TRY A COMPLETE RESEARCH CYCLE</span><h2>What this MVP demonstrates.</h2></div><div className="rules-list">{[
    ['01','Read and question','Explore a fictional manuscript or import your own draft and source excerpts. Inspect the passage behind each question and request more support when needed.'],
    ['02','Decide and revise','Explain your reasoning, write a revision or justify retaining the passage, then check the criterion and close the issue. You can also dispute a mistaken question.'],
    ['03','Explain your changes','Revisit your revised passages and explain what changed, why, and on what evidence. A demonstration review form shows how a human might assess that explanation.'],
    ['04','Review the record','Download the original and current draft text, questions, cited passages, responses, revisions, and explanations in the session record. Six fictional test cases contain deliberately placed problems for checking agent behavior.']
  ].map(([n,title,body])=><div key={n}><span>{n}</span><h3>{title}</h3><p>{body}</p></div>)}</div>
  <section className="panel scope-panel"><div><h2>What is working today</h2><p>The hosted sample uses prepared questions. Imported drafts receive general reading prompts; they are not automatically diagnosed. Documents are processed and saved in your browser. A separate local installation can use an installed language model to generate passage-linked questions.</p><p>The demo records your decisions and explanations. It does not establish that a revision is correct or that the approach improves research quality.</p><button className="text-link" onClick={onModel}>Optional setup for model-generated questions<ArrowUpRight size={14}/></button><button className="text-link" onClick={()=>download('research-test-cases.json',JSON.stringify({note:'Six fictional cases with deliberately placed issues and expected diagnoses. These are test materials, not measured model performance.',cases:SEEDS.map(c=>({...c,missing:c.groundTruth}))},null,2))}>Download the six test cases<Download size={14}/></button></div><div><h2>How the proposal will evaluate it</h2><p>Researchers will be randomly assigned to a static checklist, the learning team, or an assistant that proposes revised text, all using the same criteria.</p><ol className="evaluation-list"><li><strong>Draft quality:</strong> two independent raters assess drafts before and after revision, without knowing the condition or version.</li><li><strong>Use of feedback:</strong> records show whether researchers accept, reject, or justify challenges, and how long they engage.</li><li><strong>Authorship:</strong> researchers explain a sample of their changes; raters judge whether they can account for them.</li></ol><p>The pilot, controlled comparison, independent rating process, and active engagement measurement remain to be completed. Whether the approach builds lasting skill is a question for later work.</p></div></section>
  <div className="source-note"><BookOpen size={19}/><p>Literature reference for the six criteria: Lindebaum, D. (2026). <em>We care a lot (for Academy of Management Learning &amp; Education)—and urgent reflections on the state of AI journal policies.</em> Academy of Management Learning &amp; Education, Table 1. <a href="https://doi.org/10.5465/amle.2026.0628" target="_blank" rel="noreferrer">Read the article <ExternalLink size={12}/></a> The learning-team design is our application of the criteria, not an endorsement by the article’s author.</p></div>
</>;}

function Modal({title,children,onClose}){const ref=useRef(null);const closeRef=useRef(onClose);closeRef.current=onClose;useEffect(()=>{const previous=document.activeElement;const dialog=ref.current;const getFocusable=()=>[...dialog.querySelectorAll('button, input, textarea, select, a[href]')].filter(el=>!el.disabled);getFocusable()[0]?.focus();const key=e=>{if(e.key==='Escape'){e.preventDefault();closeRef.current();}if(e.key==='Tab'){const els=getFocusable();if(!els.length)return;if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus();}}};document.addEventListener('keydown',key);const overflow=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',key);document.body.style.overflow=overflow;previous?.focus();};},[]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className="modal" ref={ref} role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-heading"><h2 id="modal-title">{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X size={21}/></button></div>{children}</section></div>;}
async function readFile(file){if(file.size>12*1024*1024)throw new Error('Use a file smaller than 12 MB.');const ext=file.name.split('.').pop().toLowerCase();if(ext==='docx'){const {unzipSync,strFromU8}=await import('fflate');const entries=unzipSync(new Uint8Array(await file.arrayBuffer()),{filter:f=>f.name==='word/document.xml'&&f.originalSize<=3000000});if(!entries['word/document.xml'])throw new Error('The DOCX has no readable document, or its expanded text is too large.');const xml=new DOMParser().parseFromString(strFromU8(entries['word/document.xml']),'application/xml');if(xml.querySelector('parsererror'))throw new Error('The DOCX text could not be parsed.');[...xml.getElementsByTagNameNS('*','del')].forEach(node=>node.remove());return [...xml.getElementsByTagNameNS('*','p')].map(p=>[...p.getElementsByTagNameNS('*','t')].map(t=>t.textContent).join('')).join('\n\n');}if(ext==='pdf'){const pdfjs=await import('pdfjs-dist');const worker=await import('pdfjs-dist/build/pdf.worker.min.mjs?url');pdfjs.GlobalWorkerOptions.workerSrc=worker.default;const doc=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false}).promise;if(doc.numPages>80)throw new Error('Use a PDF of 80 pages or fewer for this MVP.');const pages=[];for(let i=1;i<=doc.numPages;i++){const p=await doc.getPage(i);const c=await p.getTextContent();pages.push(c.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join(''));}return pages.join('\n\n');}if(['txt','md'].includes(ext))return file.text();throw new Error('Choose a DOCX, text PDF, TXT, or Markdown file.');}
function UploadForm({onDone}){const [title,setTitle]=useState(''),[text,setText]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false),[confirm,setConfirm]=useState(false);async function upload(f){if(!f)return;setBusy(true);setError('');try{const t=await readFile(f);if(t.trim().length<200)throw new Error('Could not extract enough text. For scanned PDFs, paste OCR text instead.');setText(t);setTitle(f.name.replace(/\.[^.]+$/,'').replace(/[_-]/g,' '));}catch(e){setError(e.message);}finally{setBusy(false);}}return <form onSubmit={e=>{e.preventDefault();try{onDone(parseDraft(text,title.trim()||'Untitled manuscript'));}catch(e){setError(e.message);}}}><p className="modal-intro">Start with your own draft. Import is processed in your browser; nothing is sent to a model unless you connect and run one locally.</p><label className="upload-drop" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();upload(e.dataTransfer.files[0]);}}>{busy?<LoaderCircle className="spin" size={25}/>:<Upload size={25}/>}<strong>{busy?'Reading your document…':'Drop a manuscript here, or browse'}</strong><span>DOCX, text PDF, TXT, or Markdown · up to 12 MB</span><input type="file" accept=".docx,.pdf,.txt,.md" aria-label="Upload manuscript" onChange={e=>upload(e.target.files[0])}/></label><label className="field-label" htmlFor="draft-title">Manuscript title</label><input id="draft-title" required maxLength={160} value={title} onChange={e=>setTitle(e.target.value)} placeholder="A working title is enough"/><label className="field-label" htmlFor="draft-text">Manuscript text <span>or paste directly</span></label><textarea id="draft-text" value={text} onChange={e=>setText(e.target.value)} rows={6} maxLength={100000} placeholder="Paste your draft. Separate paragraphs with blank lines; use headings such as Introduction, Methods, and Discussion."/><label className="checkbox-label"><input type="checkbox" checked={confirm} onChange={e=>setConfirm(e.target.checked)}/><span>This is material I can use here. It excludes confidential third-party review reports. I understand this replaces the current session.</span></label>{error&&<p className="error-text" role="alert">{error}</p>}<button className="button primary full" disabled={busy||!confirm||text.trim().length<200}>Start a guided reading session<ArrowRight size={16}/></button><p className="field-help">Import formatting is simplified. Check the extracted text before starting. Add cited sources from the References tab.</p></form>;}
function ReferenceForm({onDone}){const [title,setTitle]=useState(''),[text,setText]=useState(''),[location,setLocation]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);return <form onSubmit={e=>{e.preventDefault();if(text.trim().length<40){setError('Add at least 40 characters of source text.');return;}onDone({id:crypto.randomUUID(),title:title.trim(),name:'Researcher-provided source',text:text.trim(),location:location.trim()||'Uploaded excerpt · location not supplied',synthetic:false});}}><p className="modal-intro">Add the text you want to compare with a manuscript claim. Only upload sources you are entitled to use.</p><label className="field-label" htmlFor="ref-title">Citation or source name</label><input id="ref-title" required value={title} onChange={e=>setTitle(e.target.value)} placeholder="Author (year), title" maxLength={200}/><label className="field-label" htmlFor="ref-location">Passage location</label><input id="ref-location" value={location} onChange={e=>setLocation(e.target.value)} placeholder="For example: p. 12, discussion" maxLength={200}/><label className="field-label" htmlFor="ref-file">Import a source (optional)</label><input id="ref-file" type="file" accept=".txt,.md,.docx,.pdf" onChange={async e=>{if(!e.target.files[0])return;setBusy(true);try{setText((await readFile(e.target.files[0])).slice(0,60000));}catch(e){setError(e.message);}finally{setBusy(false);}}}/><label className="field-label" htmlFor="ref-text">Source text</label><textarea id="ref-text" rows={7} required value={text} onChange={e=>setText(e.target.value)} maxLength={60000} placeholder="Paste a quotable passage or the extracted source text…"/>{error&&<p className="error-text">{error}</p>}<button className="button primary full" disabled={busy||!title.trim()||text.trim().length<40}>{busy?'Reading…':'Add to evidence library'}<Plus size={16}/></button></form>;}
function ReasonForm({label,placeholder,button,onSubmit}){const [reason,setReason]=useState(''),[error,setError]=useState('');return <form onSubmit={e=>{e.preventDefault();try{onSubmit(reason);}catch(e){setError(e.message);}}}><p className="modal-intro">The tutor can be wrong. Your disagreement and its evidence will stay in the log for assessment.</p><label className="field-label" htmlFor="reason">{label}</label><textarea id="reason" rows={6} value={reason} onChange={e=>setReason(e.target.value)} placeholder={placeholder} maxLength={6000}/>{error&&<p className="error-text">{error}</p>}<button className="button primary full" disabled={words(reason)<5}>{button}<Flag size={15}/></button></form>;}

createRoot(document.getElementById('root')).render(<App/>);
